-- =====================================================================
--  Prime Script — Contenu prêt à l'emploi (11/12) : Objections fréquentes et réponses
--
--  Ce fichier s'importe avec les autres fichiers de database/content/ :
--      php tools/import-content.php
--  (ou, en MySQL : mysql -u ... prime_script < database/content/content.sql
--   si ce fichier a été concaténé dans content.sql).
--
--  Format d'une ligne de contenu (JSON, une ligne par enregistrement) :
--    {"code": "...", "type": "...", "sector": "...", "stage": "...",
--     "service": "...", "title": "...", "position": 10, "content": "<p>…</p>"}
--
--    code     identifiant stable du bloc (réimport = mise à jour, jamais de doublon)
--    type     presentation | accroche | barrage | repondeur | decouverte |
--             argumentaire | preuve | tarif | appel_action | conclusion
--    sector   slug du secteur (architectes, artisans-btp, restauration, services-b2b)
--    stage    slug de l'étape (premier-appel, relance, closing)
--    service  slug du service (site-web, application, automatisation-ia, chatbot-ia)
--    content  HTML simple : <p>, <ul>, <li>, <strong>, <em>
--
--  Convention d'écriture : le texte à dire est en clair, l'aide au commercial
--  est sur une ligne « Conseil : … » en italique (<p><em>Conseil : …</em></p>).
-- =====================================================================

SET NAMES utf8mb4;

{"type": "objection", "question": "J'ai déjà un site, et il me suffit.", "answer": "<p>Vous avez raison de le protéger : c'est votre vitrine.</p>\n- Une question simple : il vous apporte combien de demandes par mois ?\n- Si la réponse est « aucune », ce n'est pas un site, c'est une carte de visite\n- On ne refait pas tout : l'audit gratuit dit si quelques corrections suffisent\n\n<p>Quand vous voulez, je vous envoie la note sur 100. Vous serez fixé en dix minutes.</p>\n\n<em>Conseil : ne critiquez jamais le site existant. Le client l'a choisi.</em>", "position": 1}
{"type": "objection", "question": "J'ai déjà un prestataire, ça se passe bien.", "answer": "<p>Tant mieux, un prestataire de confiance, ça ne se remplace pas.</p>\n- Je ne suis pas là pour le déloger. Juste pour être un second avis si besoin\n- Le devis écrit et le simulateur de budget sont gratuits : ça vous donne un point de comparaison\n- Beaucoup de clients nous appellent pour une seule brique qu'il ne fait pas\n\n<p>Je vous laisse le lien de l'audit gratuit. Si un jour le sujet revient, vous aurez un repère.</p>\n\n<em>Conseil : accepter le prestataire en place évite de transformer l'appel en procès.</em>", "position": 2}
{"type": "objection", "question": "C'est trop cher pour moi.", "answer": "<p>Je comprends, et c'est une vraie question.</p>\n- Ce n'est peut-être pas le bon moment : le tarif de départ pour un site commence à 790 € HT\n- On peut démarrer par une seule page, puis compléter dans six mois\n- Le devis écrit est gratuit : il vous donne un chiffre exact, pas une fourchette\n\n<p>Quel budget aviez-vous en tête, même approximatif ? Ça m'évite de vous proposer à côté.</p>\n\n<em>Conseil : « c'est trop cher » veut souvent dire « je ne vois pas la valeur ». Faites parler du besoin avant du prix.</em>", "position": 3}
{"type": "objection", "question": "Envoyez-moi un mail, je regarderai.", "answer": "<p>Avec plaisir, je vous envoie ça aujourd'hui.</p>\n- Pour que le mail soit utile : c'est plutôt sur le site ou sur vos demandes entrantes ?\n- Je mets deux exemples de votre secteur et les tarifs de départ\n- Et je vous rappelle jeudi, le temps de le lire tranquillement\n\n<p>Vous êtes joignable en fin de matinée ou plutôt en fin d'après-midi ?</p>\n\n<em>Conseil : un mail sans créneau de rappel est un mail perdu. Toujours fixer la suite.</em>", "position": 4}
{"type": "objection", "question": "Je n'ai pas le temps, là.", "answer": "<p>Je comprends, je vous prends deux minutes maximum, ou je vous rappelle.</p>\n- Une seule question, et je raccroche : vous recevez combien de demandes par semaine ?\n- Si le sujet n'est pas pour maintenant, dites-le moi franchement\n- Sinon, je vous rappelle en fin de journée ou demain matin\n\n<p>Qu'est-ce qui est le plus simple pour vous ?</p>\n\n<em>Conseil : ne dites jamais « deux minutes » puis parlez dix. La prochaine fois, personne ne répond.</em>", "position": 5}
{"type": "objection", "question": "Rappelez-moi plus tard, je suis débordé.", "answer": "<p>Pas de problème, je préfère ça à un appel bâclé.</p>\n- Je peux vous rappeler jeudi à 11 h, ou mardi en fin de journée ?\n- Si la période est chargée, on peut se donner rendez-vous le mois prochain\n- En attendant, je vous laisse un mail court avec l'essentiel\n\n<p>Dites-moi simplement le créneau qui vous arrange.</p>\n\n<em>Conseil : notez la date dans le journal de l'appel. Un rappel non noté est un rappel oublié.</em>", "position": 6}
{"type": "objection", "question": "Je dois en parler à mon associé / à ma femme.", "answer": "<p>Bien sûr, c'est une décision à deux, c'est normal.</p>\n- Est-ce qu'il ou elle a des questions types sur ce genre de projet ?\n- Je peux vous envoyer un résumé d'une page, écrit pour être montré\n- Et on peut faire un point à trois, quinze minutes, sans que je reprenne tout\n\n<p>Je vous rappelle jeudi, une fois que vous en aurez parlé ?</p>\n\n<em>Conseil : ne demandez pas « quand pourrez-vous en parler », demandez « comment vous en parlez d'habitude ».</em>", "position": 7}
{"type": "objection", "question": "Ça ne m'intéresse pas.", "answer": "<p>C'est clair, je vous remercie de me le dire.</p>\n- Une dernière chose, et je vous laisse : c'est le sujet qui ne vous intéresse pas, ou le moment ?\n- Si c'est le moment, je peux reprendre contact dans six mois\n- Si c'est le sujet, dites-le moi aussi : ça m'évitera de vous déranger\n\n<p>Dans les deux cas, je note et je respecte.</p>\n\n<em>Conseil : distinguer « pas le sujet » et « pas le moment » évite de rayer un bon prospect.</em>", "position": 8}
{"type": "objection", "question": "On n'a pas besoin de ça, on a déjà assez de clients.", "answer": "<p>C'est une bonne situation, peu d'entreprises peuvent le dire.</p>\n- Dans ce cas, la question n'est pas d'avoir plus de clients, mais de choisir lesquels\n- Un site clair filtre les demandes : les mauvaises questions arrivent moins\n- Et il vous fait gagner du temps sans amener un seul client de plus\n\n<p>Qu'est-ce qui vous coûte le plus de temps aujourd'hui, justement ?</p>\n\n<em>Conseil : basculez du « plus de clients » au « moins de temps perdu ». C'est le même produit, un autre angle.</em>", "position": 9}
{"type": "objection", "question": "Je ne comprends rien à l'informatique.", "answer": "<p>Rassurez-vous, c'est nous qui parlons technique, pas vous.</p>\n- Vous décrivez votre métier, on traduit\n- Vous n'aurez jamais de réunion sur des sujets techniques\n- À la livraison, on vous montre trois gestes : modifier un texte, ajouter une photo, publier\n\n<p>Et si vous préférez ne rien toucher, la maintenance commence à 49 € par mois, sans engagement.</p>\n\n<em>Conseil : ne minimisez pas (« c'est simple »). Reconnaissez, puis rassurez avec des gestes très concrets.</em>", "position": 10}
{"type": "objection", "question": "Je me suis déjà fait avoir par un prestataire.", "answer": "<p>Je comprends, et malheureusement vous n'êtes pas le seul.</p>\n- Chez nous, les prix de départ sont publics : vous les voyez avant de nous parler\n- Le devis écrit fixe le prix exact et le périmètre, sans surprise\n- À la livraison, le code source et tous les accès vous appartiennent\n\n<p>Vous ne dépendez de personne, y compris de nous. Ça change la relation.</p>\n\n<em>Conseil : la remise du code et des accès est votre meilleur argument face à une mauvaise expérience.</em>", "position": 11}
{"type": "objection", "question": "Vous êtes qui exactement ?", "answer": "<p>Bonne question, je me présente mieux.</p>\n- Prime Vision Solutions, une agence digitale qui travaille avec des TPE et des PME\n- Notre site est public : prestations, tarifs de départ, exemples de projets\n- Un seul interlocuteur du premier échange à la livraison\n\n<p>Je vous envoie le lien tout de suite, vous jugez par vous-même.</p>\n\n<em>Conseil : donnez le site et le téléphone de l'entreprise. Un commercial qui se cache n'inspire pas confiance.</em>", "position": 12}
{"type": "objection", "question": "Comment vous avez eu mon numéro ?", "answer": "<p>Question légitime, je vous réponds franchement.</p>\n- Votre entreprise figure dans un annuaire professionnel public\n- Nous appelons des entreprises de votre secteur, pas des particuliers\n- Si vous ne souhaitez plus d'appel, dites-le moi : je le note et je ne rappelle pas\n\n<p>Voulez-vous que je vous retire de notre liste dès maintenant ?</p>\n\n<em>Conseil : proposer le retrait soi-même désarme complètement la méfiance. Et c'est la bonne chose à faire.</em>", "position": 13}
{"type": "objection", "question": "Je préfère un prestataire local, je veux pouvoir le voir.", "answer": "<p>C'est compréhensible, on travaille mieux avec quelqu'un qu'on peut joindre.</p>\n- Nos rendez-vous se font en visio, avec partage d'écran : c'est souvent plus concret qu'un rendez-vous en agence\n- Vous avez un interlocuteur unique, joignable, pas un service client\n- Et les livraisons se font par étapes : vous voyez le travail avant de payer la suite\n\n<p>On peut faire un premier point de quinze minutes en visio, vous verrez si le courant passe.</p>\n\n<em>Conseil : la proximité est souvent un prétexte. La vraie question est « est-ce que je serai suivi ».</em>", "position": 14}
{"type": "objection", "question": "Je peux le faire moi-même, ou mon neveu s'en occupe.", "answer": "<p>Tant mieux, c'est une vraie chance d'avoir quelqu'un qui touche à ça.</p>\n- Une question : combien de temps ça vous prend, et qu'est-ce qui bloque depuis six mois ?\n- Souvent, le site existe, mais il n'est pas fini ou pas à jour\n- On peut faire uniquement ce qui bloque : les photos, la page contact, la vitesse\n\n<p>Ça vaut peut-être le coup de savoir ce qui manque précisément, non ?</p>\n\n<em>Conseil : ne dénigrez jamais le neveu. Proposez de compléter, pas de remplacer.</em>", "position": 15}
{"type": "objection", "question": "Je n'ai pas de budget en ce moment.", "answer": "<p>Je comprends, et je préfère le savoir tout de suite.</p>\n- Le devis écrit est gratuit : il vous donne un chiffre exact pour plus tard\n- Si le budget est bloqué, on peut découper en deux ou trois étapes étalées dans l'année\n- Certains projets démarrent à 790 € HT, ce n'est pas le prix d'une refonte complète\n\n<p>Quand votre prochaine fenêtre budgétaire s'ouvre, je vous rappelle ?</p>\n\n<em>Conseil : ne forcez pas. Notez la période budgétaire dans le journal : c'est un rappel à programmer.</em>", "position": 16}
{"type": "objection", "question": "Arrêtez de m'appeler, ne me rappelez plus.", "answer": "<p>Je comprends parfaitement, {contact}. Je note dès maintenant que vous ne souhaitez plus être contacté.</p>\n- Vous ne recevrez plus d'appel de notre part\n- Je vous remercie de me l'avoir dit clairement\n- Je vous souhaite une bonne journée\n\n<em>Conseil : ne tentez aucune dernière question. Honorez la demande, enregistrez « Ne plus rappeler » et raccrochez.</em>", "position": 17}
{"type": "objection", "question": "Mon site me suffit, je n'ai pas de ventes en ligne.", "answer": "<p>C'est logique : un site vitrine n'a pas besoin de vendre en ligne.</p>\n- La question, c'est plutôt : est-ce qu'il donne envie de vous appeler ?\n- Trois éléments font la différence : vos réalisations, vos tarifs de départ, un moyen de contact visible\n- Et sur téléphone, il doit se lire en dix secondes\n\n<p>Je vous propose l'audit gratuit : une note sur 100, et vous verrez s'il manque quelque chose.</p>\n\n<em>Conseil : ne parlez jamais d'e-commerce à quelqu'un qui n'en veut pas. Restez sur « être trouvé » et « rassurer ».</em>", "service": "site-web", "position": 18}
{"type": "objection", "question": "Mon site est vieux mais il fonctionne encore.", "answer": "<p>S'il fonctionne, il n'y a peut-être rien à refaire.</p>\n- Deux points à vérifier : l'affichage sur téléphone et la vitesse de chargement\n- Si ces deux points sont bons, on ne touche à rien\n- S'ils sont mauvais, on corrige seulement ça, sans refonte\n\n<p>L'audit gratuit répond à ces deux questions en quelques minutes.</p>\n\n<em>Conseil : proposer de ne rien faire est parfois la meilleure façon de gagner un client plus tard.</em>", "service": "site-web", "position": 19}
{"type": "objection", "question": "Je ne sais pas quoi écrire sur mon site.", "answer": "<p>C'est la remarque la plus fréquente, et ce n'est pas un problème.</p>\n- On écrit avec vous : on vous pose des questions sur votre métier, on rédige, vous corrigez\n- Vos mots à vous passent d'abord, on met simplement en forme\n- Les tarifs de départ incluent l'accompagnement sur les textes\n\n<p>Vous n'aurez jamais une page blanche devant vous.</p>\n\n<em>Conseil : rassurez sur le processus, pas sur le résultat. Le client veut savoir qu'il ne sera pas seul.</em>", "service": "site-web", "position": 20}
{"type": "objection", "question": "J'ai déjà une page Facebook, ça suffit.", "answer": "<p>Une page Facebook, c'est bien pour les habitués, et c'est gratuit.</p>\n- Mais quand quelqu'un cherche votre métier sur Google, il ne tombe pas sur Facebook\n- Un site, c'est vous qui le possédez : pas de changement d'algorithme, pas de compte fermé\n- On peut très bien garder la page et ajouter seulement un site simple à côté\n\n<p>Le site ne remplace pas Facebook, il le complète.</p>\n\n<em>Conseil : ne dénigrez pas les réseaux sociaux. Beaucoup de clients y tiennent beaucoup.</em>", "service": "site-web", "position": 21}
{"type": "objection", "question": "Combien de temps ça prend, un site ?", "answer": "<p>Ça dépend du périmètre, et c'est écrit dans le devis.</p>\n- Un site une page démarre avec un délai indicatif d'une à deux semaines\n- Un site professionnel de six pages, trois à quatre semaines\n- Le calendrier exact est confirmé dans le devis écrit\n\n<p>La vraie variable, c'est la disponibilité de vos contenus et de vos photos.</p>\n\n<em>Conseil : ne donnez jamais un délai de mémoire sans ajouter « indicatif, confirmé dans le devis ».</em>", "service": "site-web", "position": 22}
{"type": "objection", "question": "Est-ce que je serai premier sur Google ?", "answer": "<p>Personne d'honnête ne peut vous le promettre.</p>\n- Ce qu'on fait, c'est une base technique propre : structure claire, pages rapides, titres et descriptions\n- C'est la condition pour être trouvé, pas une garantie de première place\n- Le classement dépend ensuite de la concurrence dans votre ville et du contenu publié\n\n<p>Je préfère vous le dire maintenant que de vous vendre un rêve.</p>\n\n<em>Conseil : cet aveu de franchise fait souvent signer. Ne cédez jamais sur une promesse de position.</em>", "service": "site-web", "position": 23}
{"type": "objection", "question": "Une application, c'est réservé aux grandes entreprises.", "answer": "<p>Je comprends l'idée, mais ce n'est plus vrai.</p>\n- On en fait pour des structures de trois à trente personnes\n- Le prototype démarre à 2 900 € HT, avec un seul module\n- On commence petit : remplacer un tableur, c'est déjà une application\n\n<p>Vous utilisez déjà des tableurs partagés ? C'est souvent le point de départ.</p>\n\n<em>Conseil : ne parlez jamais d'« ERP » ou de « plateforme ». Parlez d'« un seul outil à la place de trois ».</em>", "service": "application", "position": 24}
{"type": "objection", "question": "On n'a pas les compétences en interne pour utiliser une application.", "answer": "<p>Vous n'en aurez pas besoin.</p>\n- L'outil est conçu avec les personnes qui l'utilisent, pas contre elles\n- On forme vos équipes à la livraison, et on reste joignable\n- Vous pouvez aussi prendre la maintenance à partir de 49 € par mois, sans engagement\n\n<p>Si l'outil n'est pas simple, c'est notre conception qui est en cause, pas vos équipes.</p>\n\n<em>Conseil : cette dernière phrase est à retenir mot pour mot. Elle change l'ambiance de l'appel.</em>", "service": "application", "position": 25}
{"type": "objection", "question": "C'est trop long à mettre en place.", "answer": "<p>C'est vrai que ce n'est pas un site en une semaine.</p>\n- On livre par étapes : la première version utilisable arrive bien avant la fin du projet\n- Vous validez chaque étape, donc vous ne découvrez rien à la fin\n- Et on peut commencer par un seul module, livré en quelques semaines\n\n<p>Qu'est-ce qui vous serait le plus utile en premier ?</p>\n\n<em>Conseil : la livraison par étapes est votre meilleure réponse à la peur du projet interminable.</em>", "service": "application", "position": 26}
{"type": "objection", "question": "On a déjà un logiciel métier, ça ne sert à rien.", "answer": "<p>Si votre logiciel fait le travail, il faut le garder.</p>\n- La question : est-ce qu'il communique avec vos autres outils, ou est-ce que vous ressaisissez ?\n- C'est souvent là qu'on intervient : faire dialoguer l'existant\n- On ne remplace pas un logiciel métier, on bouche les trous autour\n\n<p>Qu'est-ce que vous devez ressaisir à la main aujourd'hui ?</p>\n\n<em>Conseil : les projets d'application échouent quand ils remplacent un outil métier. Vendez l'interconnexion.</em>", "service": "application", "position": 27}
{"type": "objection", "question": "Ça coûte combien, exactement ?", "answer": "<p>Le point de départ est 2 900 € HT pour un prototype, et 7 900 € HT pour une application complète.</p>\n- Ce sont des tarifs de départ : le prix exact dépend du nombre d'écrans et des connexions\n- Le devis écrit gratuit fixe le montant et ce qui est inclus\n- On peut commencer par un module seul pour rester dans un budget plus serré\n\n<p>Quel budget avez-vous en tête ? Je vous dirai franchement si c'est jouable.</p>\n\n<em>Conseil : annoncez le prix et taisez-vous. Le silence fait plus de travail que trois arguments.</em>", "service": "application", "position": 28}
{"type": "objection", "question": "Et si on veut changer plus tard ? On sera bloqué.", "answer": "<p>Non, et c'est un engagement écrit de notre part.</p>\n- Le code source vous est remis à la livraison\n- Les accès serveur et nom de domaine vous appartiennent\n- Une autre équipe peut reprendre le projet, sans notre autorisation\n\n<p>Vous ne signez pas un abonnement, vous achetez un outil.</p>\n\n<em>Conseil : proposez de montrer cette clause dans le devis. Un engagement écrit vaut mille promesses.</em>", "service": "application", "position": 29}
{"type": "objection", "question": "L'automatisation, c'est trop compliqué à mettre en place.", "answer": "<p>C'est souvent l'image que ça donne, mais la mise en place se fait sans vous.</p>\n- On commence par un audit du temps perdu : quelles tâches reviennent, combien de fois\n- On automatise une seule tâche d'abord, celle qui coûte le plus\n- Vous validez ce qui part, pendant les premières semaines\n\n<p>Les automatisations démarrent à 1 500 € HT. On peut commencer petit.</p>\n\n<em>Conseil : ne décrivez jamais la plomberie technique. Décrivez la tâche qui disparaît.</em>", "service": "automatisation-ia", "position": 30}
{"type": "objection", "question": "On ne sait pas ce qu'on pourrait automatiser.", "answer": "<p>C'est exactement à ça que sert le premier échange.</p>\n- Trois questions suffisent : qu'est-ce qui revient, qui le fait, combien de temps ça prend\n- On repère souvent deux ou trois tâches très simples, comme les relances de devis\n- Vous repartez avec une liste, même si vous ne nous confiez rien\n\n<p>On peut faire cet audit par téléphone en vingt minutes.</p>\n\n<em>Conseil : un audit offert qui se termine sans devis est un bon investissement. Ne le monnayez pas.</em>", "service": "automatisation-ia", "position": 31}
{"type": "objection", "question": "L'IA, ça fait des erreurs, je ne veux pas de ça.", "answer": "<p>Vous avez raison de vous méfier, c'est le vrai sujet.</p>\n- Chaque automatisation a un contrôle humain avant l'envoi\n- L'assistant ne répond que sur vos informations validées, jamais au-delà\n- On teste les réponses sur des cas réels avant la mise en service\n\n<p>Rien ne part sans votre accord, au moins pendant les premières semaines.</p>\n\n<em>Conseil : ne dites jamais « ça ne se trompe pas ». Dites « ça ne part pas sans vous ».</em>", "service": "automatisation-ia", "position": 32}
{"type": "objection", "question": "Mes données, elles vont où ?", "answer": "<p>Question essentielle, et la réponse est simple.</p>\n- Les données restent dans vos outils ou sur un serveur que vous validez\n- On ne collecte que ce qui est nécessaire au fonctionnement\n- Les règles de conservation sont définies avec vous, conformément au RGPD\n\n<p>Tout est écrit dans le devis avant de commencer, pas après.</p>\n\n<em>Conseil : ne promettez pas « 100 % sécurisé ». Dites ce qui est prévu, noir sur blanc.</em>", "service": "automatisation-ia", "position": 33}
{"type": "objection", "question": "Ça va me faire perdre des clients si c'est automatique.", "answer": "<p>C'est une crainte fréquente, et légitime.</p>\n- On n'automatise pas la relation client, on automatise les tâches répétitives\n- Un devis relancé automatiquement, c'est un client qui se sent suivi, pas ignoré\n- Un humain peut reprendre la main à tout moment\n\n<p>L'automatisation remplace la relance oubliée, pas la conversation.</p>\n\n<em>Conseil : donnez un exemple vécu, pas une théorie. « La relance du devis » parle à tout le monde.</em>", "service": "automatisation-ia", "position": 34}
{"type": "objection", "question": "Mes clients n'aiment pas parler à un robot.", "answer": "<p>C'est vrai pour beaucoup de gens, et on en tient compte.</p>\n- L'assistant ne se fait pas passer pour un humain : il est identifié\n- À la moindre demande sensible, il passe la main avec un résumé\n- La plupart des gens préfèrent une réponse à 22 h qu'aucune réponse\n\n<p>Le but n'est pas de remplacer la conversation, c'est d'éviter le silence.</p>\n\n<em>Conseil : proposez de tester la démo soi-même. L'expérience vaut mieux que l'argument.</em>", "service": "chatbot-ia", "position": 35}
{"type": "objection", "question": "Ça va se tromper et dire n'importe quoi.", "answer": "<p>C'est le risque numéro un, et il se maîtrise.</p>\n- L'assistant ne répond qu'à partir de vos informations validées\n- Il ne donne jamais de prix ferme et ne prend aucun engagement\n- Vous relisez et validez chaque réponse avant la mise en service\n\n<p>S'il ne sait pas, il le dit et passe la main. C'est prévu.</p>\n\n<em>Conseil : « il ne sait pas, il le dit » est la phrase qui rassure le plus. Gardez-la.</em>", "service": "chatbot-ia", "position": 36}
{"type": "objection", "question": "On répond déjà au téléphone et par mail.", "answer": "<p>Et c'est très bien, c'est le cœur du métier.</p>\n- La question, c'est le soir et le week-end, quand personne ne répond\n- Et les questions répétitives : horaires, accès, tarifs de départ\n- L'assistant traite celles-là, vous gardez les vraies conversations\n\n<p>Combien de messages attendez-vous jusqu'au lendemain matin ?</p>\n\n<em>Conseil : positionnez le chatbot comme un filtre, pas comme un remplaçant.</em>", "service": "chatbot-ia", "position": 37}
{"type": "objection", "question": "On a déjà un formulaire de contact.", "answer": "<p>C'est déjà une bonne base, tout le monde n'en a pas.</p>\n- Un formulaire attend une réponse. Un assistant répond tout de suite\n- La différence se voit le soir : le visiteur part, ou il obtient sa réponse\n- Et l'assistant peut qualifier la demande avant qu'elle vous arrive\n\n<p>Le formulaire reste : l'assistant le complète.</p>\n\n<em>Conseil : ne remplacez rien de ce que le client a déjà. Ajoutez.</em>", "service": "chatbot-ia", "position": 38}
{"type": "objection", "question": "990 € pour un chatbot, ça me paraît beaucoup.", "answer": "<p>Je comprends, ça se compare à autre chose.</p>\n- C'est le point de départ : installation, réponses aux questions fréquentes, historique des conversations\n- Ça représente une à deux semaines de mise en service\n- Si vous devez embaucher quelqu'un pour répondre le soir, le calcul est vite fait\n\n<p>Vous pouvez tester la démo gratuite avant de décider quoi que ce soit.</p>\n\n<em>Conseil : ne défendez pas le prix, comparez-le. Le client fera le calcul lui-même.</em>", "service": "chatbot-ia", "position": 39}
{"type": "objection", "question": "Et si un client pose une question compliquée ?", "answer": "<p>Il passe la main, c'est prévu dès le départ.</p>\n- L'assistant détecte les demandes hors périmètre : devis complexe, réclamation, cas particulier\n- Il transmet la conversation avec un résumé et les coordonnées\n- Vous rappelez en sachant déjà de quoi il s'agit\n\n<p>Vous ne perdez pas le client, vous arrivez préparé.</p>\n\n<em>Conseil : le passage à l'humain est un argument de vente, pas une limite. Présentez-le comme tel.</em>", "service": "chatbot-ia", "position": 40}
{"type": "objection", "question": "Je travaille par bouche-à-oreille, ça me suffit.", "answer": "<p>C'est le meilleur signe qu'une entreprise travaille bien.</p>\n- Le bouche-à-oreille reste votre premier canal, ça ne change pas\n- Mais celui qui vous recommande tape votre nom sur Google avant d'appeler\n- S'il ne trouve rien, il doute. Un site simple règle ça\n\n<p>Vos clients vous recommandent, mais qu'est-ce qu'ils trouvent en vous cherchant ?</p>\n\n<em>Conseil : ne demandez jamais au client de choisir entre le bouche-à-oreille et le site. Les deux coexistent.</em>", "sector": "artisans-btp", "position": 41}
{"type": "objection", "question": "Mes clients réservent par téléphone, ça marche très bien.", "answer": "<p>Bien sûr, et le téléphone reste le canal principal.</p>\n- Le sujet, c'est le soir et le week-end, quand la salle est pleine ou fermée\n- Un client qui ne joint personne réserve ailleurs\n- La réservation en ligne ne remplace pas le téléphone : elle prend ce que vous ne pouvez pas prendre\n\n<p>Vous perdez combien de demandes le samedi soir, à votre avis ?</p>\n\n<em>Conseil : ne parlez jamais de remplacer le téléphone face à un restaurateur. Parlez des heures creuses.</em>", "sector": "restauration", "position": 42}
{"type": "objection", "question": "Mes projets se vendent sur recommandation, pas sur Internet.", "answer": "<p>C'est souvent vrai dans l'architecture, et c'est une force.</p>\n- Mais la recommandation se vérifie : on tape votre nom avant de vous appeler\n- Un site avec vos réalisations donne du poids à cette recommandation\n- Et il vous évite d'envoyer un PDF de vingt pages à chaque nouveau contact\n\n<p>Vos projets sont montrés comment aujourd'hui ?</p>\n\n<em>Conseil : ne parlez pas de « visibilité », parlez de « crédibilité » et de « gagner du temps ».</em>", "sector": "architectes", "position": 43}
{"type": "objection", "question": "On vend surtout par appels d'offres et recommandations.", "answer": "<p>C'est le modèle de beaucoup d'entreprises de services, et il fonctionne.</p>\n- Le site n'amène pas toujours l'appel d'offres, mais il est regardé avant\n- Une page claire par domaine d'expertise aide à être retenu sur une short-list\n- Et les relances de devis, elles, s'appliquent à tous les canaux\n\n<p>Quand vous êtes présélectionné, le client regarde quoi avant de choisir ?</p>\n\n<em>Conseil : en B2B, le site sert souvent à confirmer un choix déjà fait. C'est un argument suffisant.</em>", "sector": "services-b2b", "position": 44}
